84: void pointMul(const Point * pointP, Point * pointR, const mpz_t d, Curve * curve) {
85:     int isInf = 1;
86:     char * dbits = mpz_get_str(NULL, 2, d);
87: 
88:     Point p, tmp;
89:     mpz_inits(tmp.x, tmp.y, pointR->x, pointR->y, NULL);
90:     mpz_init_set(p.x, pointP->x);
91:     mpz_init_set(p.y, pointP->y);
92: 
