94:         if(dbits[i] == '1') {
95:             if(isInf == 1) {
96:                 mpz_set(pointR->x, p.x);
97:                 mpz_set(pointR->y, p.y);
98:                 isInf = 0;
99:             }
100:             else {
101:                 mpz_set(tmp.x, pointR->x);
102:                 mpz_set(tmp.y, pointR->y);
103:                 pointAdd(&p, &tmp, pointR, curve);
104:             }
105:         }
106: 
107:         mpz_set(tmp.x, p.x);
108:         mpz_set(tmp.y, p.y);
109:         pointDouble(&tmp, &p, curve);
110:     }
